import { z } from 'zod';
import type { DataCrossCheck } from '../data/game-data';

/**
 * Every province's starting buildings (F85), `data/building_start.json`.
 * Generated by `npm run import:starting-data` from real 2024 production
 * figures (`packages/tools/starting-data/`); never edit it by hand.
 *
 * Each province lists its buildings as `[building, method, level]`: the
 * building type's id, the production method it runs and its level.
 */
export const buildingStartFileSchema = z.strictObject({
  /** The year the numbers describe: the campaign's first year. */
  year: z.int().min(2000).max(2100),
  /** Where the figures come from (shown in the import's report and the credits). */
  sources: z.array(
    z.strictObject({
      title: z.string().min(1),
      url: z.string(),
      licence: z.string(),
      edition: z.string(),
    }),
  ),
  provinces: z.array(
    z.strictObject({
      id: z.string(),
      buildings: z.array(z.tuple([z.string(), z.string(), z.int().min(1).max(65535)])),
    }),
  ),
});

export type BuildingStartFile = z.infer<typeof buildingStartFileSchema>;

/** Cross-file checks: known provinces, buildings and methods; each building once per province. */
export const checkBuildingStart: DataCrossCheck = (data, report) => {
  const file = 'building_start.json';
  const start = data.buildingStart;
  const issue = (path: string, message: string) => report({ file, path, message });
  if (start.year !== data.gameConfig.startDate.year)
    issue(
      'year',
      `the starting data is for ${start.year}, but the campaign starts in ${data.gameConfig.startDate.year} (game_config.json)`,
    );
  const provinceIds = new Set(data.provinces.provinces.map((p) => p.id));
  const methods = new Map(
    data.buildings.buildings.map((b) => [b.id, b.methods.map((method) => method.id)]),
  );
  const seen = new Set<string>();
  start.provinces.forEach((province, index) => {
    const at = `provinces.${index}`;
    if (!provinceIds.has(province.id))
      issue(`${at}.id`, `unknown province "${province.id}" (not in provinces.json)`);
    if (seen.has(province.id)) issue(`${at}.id`, `duplicate province "${province.id}"`);
    seen.add(province.id);
    const buildingsHere = new Set<string>();
    province.buildings.forEach(([building, method], b) => {
      const known = methods.get(building);
      if (!known)
        issue(`${at}.buildings.${b}`, `unknown building "${building}" (not in buildings.json)`);
      else if (!known.includes(method))
        issue(`${at}.buildings.${b}`, `"${building}" has no production method "${method}"`);
      if (buildingsHere.has(building))
        issue(`${at}.buildings.${b}`, `"${building}" is listed twice in this province`);
      buildingsHere.add(building);
    });
  });
};
